54	
55	namespace
56	{
57	constexpr char const* kATTENTION_PLUGIN_VERSION{"1"};
58	constexpr char const* kATTENTION_PLUGIN_NAME{"AttentionPlugin"};
59	
60	// Select KV cache storage datatype based on FP8 enablement
61	static inline DataType selectKvCacheDataType(bool enableFp8KVCache)
62	{
63	    return enableFp8KVCache ? DataType::kFP8 : DataType::kHALF;
64	}
65	
66	// Define the mapping of input and output indices of the AttentionPlugin.
67	constexpr int32_t kIN_Q_IDX{0};
68	constexpr int32_t kIN_K_IDX{1};
69	constexpr int32_t kIN_V_IDX{2};
70	constexpr int32_t kIN_KV_CACHE_IDX{3};
71	constexpr int32_t kIN_CONTEXT_LENGTH_IDX{4};
72	constexpr int32_t kIN_ROPE_COS_SIN_IDX{5};
73	constexpr int32_t kIN_KV_CACHE_START_IDX{6};
74	constexpr int32_t kIN_OPTIONAL_ATTN_MASK_IDX{7};
75	constexpr int32_t kIN_OPTIONAL_ATTN_POS_ID_IDX{8};
76	constexpr int32_t kOUT_ATTENTION_IDX{0};
77	constexpr int32_t kOUT_KV_CACHE_IDX{1};
78	
79	// Reflect the count of Inputs and Outputs of the AttentionPlugin,
80	// these definitions shall be consistent.
81	constexpr int32_t kNUM_REQUIRED_INPUTS{7};
82	constexpr int32_t kNUM_TREE_ATTN_OPTIONAL_INPUTS{2};
83	constexpr int32_t kNUM_VISION_BLOCK_OPTIONAL_INPUTS{1};
84	constexpr int32_t kNUM_REQUIRED_OUTPUTS{2};
85	
86	// Support Tree Attention decoding schema up to 128 tokens in the draft tree per batch.
87	// We are unable to check this property during shape checking since prefill length is much larger than this value.
88	constexpr int64_t kMAX_EAGLE_DECODING_TOKENS = 128;
89	
90	enum class AttentionExecutionMode
91	{
92	    kINVALID,
93	    kNORMAL_PREFILL,
94	    kCHUNKED_PREFILL,
95	    kVANILLA_DECODING,
96	    kTREE_DECODING
97	};
98	
99	AttentionExecutionMode deduceModeVanilla(rt::Tensor const& qInputTensor, rt::Tensor const& kvCacheStartIdxTensor)
100	{
101	    // Empty KVCache Start indices means normal prefill without previous KVCache. Notice single token is also a valid
102	    // prefill length.
103	    if (kvCacheStartIdxTensor.getShape()[0] == 0)
104	    {
105	        return AttentionExecutionMode::kNORMAL_PREFILL;
106	    }
107	
108	    // Otherwise, distinguish between chunked prefill and vanilla decoding based on the runtime Sequence Length.
109	    // Vanilla decoding should always have runtime sequence length of 1.
110	    int64_t const runtimeSeqLen = qInputTensor.getShape()[1];
111	    if (runtimeSeqLen > 1)
112	    {
113	        return AttentionExecutionMode::kCHUNKED_PREFILL;
114	    }
115	    return AttentionExecutionMode::kVANILLA_DECODING;
116	}
117	
118	AttentionExecutionMode deduceModeTreeAttention(
119	    rt::Tensor const& qInputTensor, rt::Tensor const& kvCacheStartIdxTensor, rt::Tensor const& attentionPosIdTensor)
120	{
121	    // Normal prefill if there is no previous KVCache.
122	    if (kvCacheStartIdxTensor.getShape()[0] == 0)
123	    {
124	        return AttentionExecutionMode::kNORMAL_PREFILL;
125	    }
126	
127	    // Under tree attention, each token will be associated with a position id (within the sequence) to perform correct
128	    // positional encoding. Even for casual decoding with multiple tokens, the position id is still required to be
129	    // supplied.
130	
131	    // Note, chunked prefill is very similar to tree decoding, the difference is chunked prefill will have contiguous
132	    // tokens in the sequence while tree decoding has a "tree" structure described by attention mask and position ids.
133	    // By convention, we will supply 1 shape for position id tensor under prefill execution.
134	    int64_t const runtimeSeqLen = qInputTensor.getShape()[1];
135	    int64_t const positionIdLen = attentionPosIdTensor.getShape()[1];
136	
137	    if (runtimeSeqLen == 1)
138	    {
139	        // Also supports single token decoding mode when tree attention is enabled.
140	        return AttentionExecutionMode::kVANILLA_DECODING;
141	    }
142	    else if (positionIdLen == runtimeSeqLen)
143	    {
144	        return AttentionExecutionMode::kTREE_DECODING;
145	    }
146	    else if (positionIdLen == 1)
147	    {
148	        return AttentionExecutionMode::kCHUNKED_PREFILL;
149	    }
150	
151	    return AttentionExecutionMode::kINVALID;
152	}
153	
154	bool loadFMHAKernels(
155	    bool& useCuteDslFMHA, int32_t headSize, int32_t smVersion, nvinfer1::DataType dataType, bool useSlidingWindow)
156	{
157	    bool canImplementFMHA = false;
158	#ifdef CUTE_DSL_FMHA_ENABLED
159	    if (useCuteDslFMHA)
160	    {
161	        if (CuteDslFMHARunner::canImplement(headSize, smVersion) && CuteDslFMHARunner::loadLLMKernelModule())
162	        {
163	            canImplementFMHA = true;
164	            LOG_DEBUG("CuTe DSL FMHA kernel loaded for SM%d", smVersion);
165	        }
166	        else
167	        {
168	            LOG_DEBUG("CuTe DSL FMHA not available (headSize=%d, SM%d), falling back to FMHA_v2", headSize, smVersion);
169	            useCuteDslFMHA = false;
170	        }
171	    }
172	    if (!useCuteDslFMHA)
173	#endif
174	    {
175	        canImplementFMHA = ContextFMHARunner::canImplement(headSize, smVersion, dataType,
176	            AttentionInputLayout::SEPARATE_Q_K_V,
177	            useSlidingWindow ? ContextAttentionMaskType::SLIDING_OR_CHUNKED_CAUSAL : ContextAttentionMaskType::CAUSAL);
178	        if (canImplementFMHA)
179	        {
180	            if (!ContextFMHARunner::loadContextFMHAKernels(smVersion, dataType))
181	            {
182	                LOG_ERROR("Failed to load FMHA_v2 cubins for SM%d", smVersion);
183	                canImplementFMHA = false;
184	            }
185	        }
186	    }
187	    return canImplementFMHA;
188	}
189	
190	// Workspace layout (cumulative, worst-case across all execution paths):
191	//
192	//   Slot  | Shape                            | Type  | Used by
193	//   ------+----------------------------------+-------+------------------------------------------
194	//   0     | [B+1]                            | INT32 | cuQSeqLens          (prefill)
195	//   1     | [B+1]                            | INT32 | cuKVSeqLens         (prefill)
196	//   2     | [B]                              | INT32 | kvCacheEndIdxs      (prefill)
197	//   3     | [B+1]                            | INT32 | paddedCuKVSeqLens   (prefill, CuTe DSL)
198	//   4     | [B, 2, Hkv, Smax, D]             | HALF  | transposedKV        (FMHA_v2 chunked prefill)
199	//   5*    | [B, S, Hq, D]                    | FP8   | fp8Q                (CuTe DSL + FP8 prefill only)
200	//   6*    | [B, S] x 2                       | INT32 | blockBegin/blockEnd (vision FFPA overlay prefill only)
201	//   7*    | [packedMaskWords(B, S, S)]       | INT32 | packedMask          (vision FMHA CUSTOM_MASK prefill only)
202	//   8*    | [B+1]                            | INT32 | cuMaskRows          (vision FMHA CUSTOM_MASK prefill only)
203	//
204	//   * Slots 5-8 are conditionally allocated (CuTe DSL + FP8 KV cache /
205	//     vision-block attention respectively).
206	//
207	// Total allocation is the sum of all conditional slots (safe upper bound).
208	size_t getAttentionWorkspaceSize(int64_t batchSize, int64_t seqLen, int64_t kvCacheCapacity, int32_t numQHeads,
209	    int32_t numKVHeads, int32_t headSize, bool useCuteDslFMHA, bool enableFp8KVCache, bool enableVisionBlockAttention)
210	{
211	    size_t workspaceSize = 0;
212	
213	    // CuQSeqLens for FMHA.
214	    workspaceSize = accumulateWorkspaceSize(workspaceSize, {batchSize + 1}, DataType::kINT32);
215	
216	    // Always reserve workspace memory to prepare for chunked prefill decoding. The implementation should be further
217	    // optimized to avoid the workspace size overhead.
218	    workspaceSize = accumulateWorkspaceSize(workspaceSize, rt::Coords{batchSize + 1}, DataType::kINT32);
219	    workspaceSize = accumulateWorkspaceSize(workspaceSize, rt::Coords{batchSize}, DataType::kINT32);
220	    workspaceSize = accumulateWorkspaceSize(workspaceSize, rt::Coords{batchSize + 1}, DataType::kINT32);
221	    workspaceSize = accumulateWorkspaceSize(
222	        workspaceSize, rt::Coords{batchSize, 2, numKVHeads, kvCacheCapacity, headSize}, DataType::kHALF);
223	
224	    // FP8 Q output: RoPE kernel writes FP8 Q to this workspace buffer (CuTe DSL FMHA path).
225	    if (useCuteDslFMHA && enableFp8KVCache)
226	    {
227	        workspaceSize = accumulateWorkspaceSize(
228	            workspaceSize, rt::Coords{batchSize, seqLen, numQHeads, headSize}, DataType::kFP8);
229	    }
230	
231	    // Per-position vision-block intervals for the FFPA overlay prefill, plus
232	    // the FMHA CUSTOM_MASK packed mask (+ per-batch mask-row offsets) for the
233	    // sliding d256 prefill.
234	    if (enableVisionBlockAttention)
235	    {
236	        workspaceSize = accumulateWorkspaceSize(workspaceSize, rt::Coords{batchSize, seqLen}, DataType::kINT32);
237	        workspaceSize = accumulateWorkspaceSize(workspaceSize, rt::Coords{batchSize, seqLen}, DataType::kINT32);
238	        workspaceSize = accumulateWorkspaceSize(
239	            workspaceSize, rt::Coords{kernel::getPackedMaskSizeInWords(batchSize, seqLen, seqLen)}, DataType::kINT32);
240	        workspaceSize = accumulateWorkspaceSize(workspaceSize, rt::Coords{batchSize + 1}, DataType::kINT32);
241	    }
242	
243	    return workspaceSize;
244	}
