254	// TODO: Extend the attention kernel to consume interleaved KV cache directly and remove this extra
255	// deinterleaveKVCache call (WAR for current kernel limitation).
256	std::pair<rt::Tensor, rt::Tensor> AttentionPlugin::deinterleaveKVCache(rt::Tensor const& kvCacheTensor,
257	    std::byte*& workspacePtr, int32_t batchSize, int32_t numKVHeads, int32_t kvCacheCapacity, int32_t headSize,
258	    int32_t seqLen, cudaStream_t stream)
259	{
260	    // seqLen == 0 means copy full capacity; otherwise copy only first seqLen tokens (compact).
261	    int32_t const outSeqDim = (seqLen > 0) ? seqLen : kvCacheCapacity;
262	    size_t const halfSize = static_cast<size_t>(batchSize) * outSeqDim * numKVHeads * headSize;
263	    rt::Tensor kvWorkspaceTensor
264	        = assignTensorFromWorkspace(workspacePtr, {batchSize, 2, numKVHeads, outSeqDim, headSize}, DataType::kHALF);
265	    half* ptr = kvWorkspaceTensor.dataPointer<half>();
266	    rt::Tensor kTensor(
267	        ptr, rt::Coords{batchSize, outSeqDim, numKVHeads, headSize}, rt::DeviceType::kGPU, DataType::kHALF);
268	    rt::Tensor vTensor(
269	        ptr + halfSize, rt::Coords{batchSize, outSeqDim, numKVHeads, headSize}, rt::DeviceType::kGPU, DataType::kHALF);
270	
271	    // seqLen > 0: compact copy of first seqLen tokens; seqLen == 0: full copy (also handles FP8 dequant).
272	    kernel::cvtKVLayoutBHSDToSplitKV(kvCacheTensor, kTensor, vTensor, rt::Tensor{}, seqLen, stream);
273	    return std::make_pair(std::move(kTensor), std::move(vTensor));
274	}
275	
276	#ifdef CUTE_DSL_FFPA_ENABLED
277	void AttentionPlugin::dispatchFFPAKernel(half const* q, half const* k, half const* v, half* o, int32_t const* cuSeqLenQ,
278	    int32_t const* cuSeqLenK, int32_t batchSize, int32_t seqlenQ, int32_t seqlenK, cudaStream_t stream)
279	{
280	    CuteDslFFPAParams ffpaParams{};
281	    ffpaParams.q = q;
282	    ffpaParams.k = k;
283	    ffpaParams.v = v;
284	    ffpaParams.o = o;
285	    ffpaParams.cuSeqLenQ = cuSeqLenQ;
286	    ffpaParams.cuSeqLenK = cuSeqLenK;
287	    ffpaParams.batchSize = batchSize;
288	    ffpaParams.seqlenQ = seqlenQ;
289	    ffpaParams.seqlenK = seqlenK;
290	    ffpaParams.numQHeads = mNumQHeads;
291	    ffpaParams.numKVHeads = mNumKVHeads;
292	    ffpaParams.headDim = mHeadSize;
293	    ffpaParams.softmaxScale = mAttentionScale;
294	    CuteDslFFPARunner::run(ffpaParams, stream);
295	}
296	#endif
