298	bool AttentionPlugin::canUseFFPAOverlayForVisionPrefill() const noexcept
299	{
300	#ifdef CUTE_DSL_FFPA_ENABLED
301	    // FFPA is full-causal: only the non-sliding (global) layers may use the
302	    // overlay.  mCanImplementFFPA implies headSize == 512 and a loaded module.
303	    return mCanImplementFFPA && mSlidingWindowSize <= 0
304	        && CuteDslFFPARunner::canImplementVisionBlock(mHeadSize, mSMVersion);
305	#else
306	    return false;
307	#endif
308	}
309	
310	void AttentionPlugin::enforceVisionBlockKernelSupport() const
311	{
312	    // Vision-block attention has no fallback path: every layer must have a
313	    // production kernel, otherwise fail loudly at plugin construction (a
314	    // clear build/load-time error beats a silently wrong deployment).
315	    if (mHeadSize == 512 && mSlidingWindowSize <= 0)
316	    {
317	        ELLM_CHECK(canUseFFPAOverlayForVisionPrefill(),
318	            "AttentionPlugin: vision-block prefill (headSize=512, full-causal) requires the CuTe DSL FFPA d512 "
319	            "vision-block overlay kernel, which is unavailable on SM"
320	                + std::to_string(mSMVersion)
321	                + " in this build. Rebuild with a CuTe DSL FFPA artifact (ffpa_d512_causal_visionblock variant) "
322	                  "matching this SM.");
323	    }
324	    else
325	    {
326	        ELLM_CHECK(mCanImplementCustomMaskFMHA,
327	            "AttentionPlugin: vision-block prefill requires FMHA_v2 CUSTOM_MASK cubins (SEPARATE_Q_K_V) for headSize="
328	                + std::to_string(mHeadSize) + " on SM" + std::to_string(mSMVersion)
329	                + ", which are missing from the cubin metadata table.");
330	    }
331	    ELLM_CHECK(mCanImplementXQA,
332	        "AttentionPlugin: vision-block decode requires XQA decode kernels for Hq=" + std::to_string(mNumQHeads)
333	            + ", Hkv=" + std::to_string(mNumKVHeads) + ", headSize=" + std::to_string(mHeadSize) + " on SM"
334	            + std::to_string(mSMVersion) + ", which are not available.");
335	}
336	
337	AttentionPlugin::AttentionPlugin(std::string const& name, int32_t numQHeads, int32_t numKVHeads, int32_t headSize,
338	    int32_t enableTreeAttention, int32_t enableFp8KVCache, int32_t enableVisionBlockAttention,
339	    int32_t slidingWindowSize, std::vector<float> const& qkvScales, std::optional<float> attentionScale)
340	    : mLayerName(name)
341	    , mNumQHeads(numQHeads)
342	    , mNumKVHeads(numKVHeads)
343	    , mHeadSize(headSize)
344	    , mAttentionScale(resolveAttentionScale(attentionScale, headSize))
345	    , mEnableTreeAttention(enableTreeAttention)
346	    , mEnableVisionBlockAttention(enableVisionBlockAttention)
347	    , mEnableFp8KVCache(enableFp8KVCache)
348	    , mQkvScales(enableFp8KVCache ? qkvScales : std::vector<float>{1.f, 1.f, 1.f})
349	    , mSlidingWindowSize(slidingWindowSize)
350	{
351	    ELLM_CHECK(!(mEnableTreeAttention && mEnableVisionBlockAttention),
352	        "Tree attention and vision block attention are mutually exclusive.");
353	    ELLM_CHECK(!mEnableVisionBlockAttention || !mEnableFp8KVCache, "Vision block attention requires an FP16 KV cache.");
354	    ELLM_CHECK(!mEnableFp8KVCache || mQkvScales.size() == 3,
355	        "FP8 KV cache enabled but qkv_scales has "
356	            + std::to_string(mQkvScales.size()) + " elements (expected 3). "
357	            "Re-export the model to include QKV scales [q, k, v].");
358	
359	    mSMVersion = getSMVersion();
360	    applyThorSMRenumberWAR(mSMVersion);
361	
362	    LOG_DEBUG("AttentionPlugin FMHA path: %s, sliding_window: %s", mUseCuteDslFMHA ? "CuTe DSL FMHA" : "FMHA_v2",
363	        mSlidingWindowSize > 0 ? std::to_string(mSlidingWindowSize).c_str() : "disabled");
364	
365	    mCanImplementFMHA = loadFMHAKernels(mUseCuteDslFMHA, mHeadSize, mSMVersion, mDataType, mSlidingWindowSize > 0);
366	
367	    // XQA decode kernels are needed for decode path when available.
368	    bool const useSpecDecode = true;
369	    bool const usePagedKVCache = false;
370	    mCanImplementXQA = DecoderXQARunner::canImplement(mNumQHeads, mNumKVHeads, mHeadSize, mSMVersion, mDataType,
371	        selectKvCacheDataType(mEnableFp8KVCache), usePagedKVCache);
372	    if (mCanImplementXQA)
373	    {
374	        DecoderXQARunner::loadDecodeXQAKernels(
375	            mSMVersion, mDataType, selectKvCacheDataType(mEnableFp8KVCache), useSpecDecode, usePagedKVCache);
376	    }
377	
378	    // Kernel selection priority for prefill and decode:
379	    //   1. Vision-block attention        — per-layer routing: FFPA d512 vision-block overlay
380	    //      (full-causal d512 prefill) or FMHA CUSTOM_MASK (sliding d256-class prefill); XQA
381	    //      decode.  All three are hard requirements (no fallback; construction fails loudly).
382	    //   2. FMHA (prefill) + XQA (decode) — standard path for most head sizes.
383	    //   3. FFPA (prefill) + XQA (decode) — fallback for headSize=512 where FMHA has no cubins.
384	    //   4. FFPA (prefill) only           — headSize=512 without XQA decode support.
385	    //   5. XQA (decode) only             — prefill unsupported for this head size.
386	    //   6. None                          — fatal, cannot serve this configuration.
387	
388	    // FMHA unavailable — try to load the FFPA d512 kernel module.  It serves
389	    // both the plain headSize=512 prefill and (when the visionblock AOT
390	    // variant is present) the vision-block overlay prefill.
391	    if (!mCanImplementFMHA)
392	    {
393	#ifdef CUTE_DSL_FFPA_ENABLED
394	        if (mHeadSize == 512 && CuteDslFFPARunner::canImplement(mHeadSize, mSMVersion, mNumQHeads, mNumKVHeads))
395	        {
396	            if (CuteDslFFPARunner::loadKernelModule())
397	            {
398	                mCanImplementFFPA = true;
399	            }
400	        }
401	#endif
402	    }
403	
404	    if (mEnableVisionBlockAttention)
405	    {
406	        // Sliding d256-class prefill production path: FMHA_v2 CUSTOM_MASK.
407	        // Availability is discovered from the cubin metadata table.
408	        mCanImplementCustomMaskFMHA = ContextFMHARunner::canImplement(mHeadSize, mSMVersion, mDataType,
409	                                          AttentionInputLayout::SEPARATE_Q_K_V, ContextAttentionMaskType::CUSTOM_MASK)
410	            && ContextFMHARunner::loadContextFMHAKernels(mSMVersion, mDataType);
411	
412	        enforceVisionBlockKernelSupport();
413	
414	        LOG_INFO(
415	            "AttentionPlugin: vision-block attention (headSize=%d, Hq=%d, Hkv=%d, window=%d) — prefill via %s, "
416	            "decode via XQA.",
417	            mHeadSize, mNumQHeads, mNumKVHeads, mSlidingWindowSize,
418	            canUseFFPAOverlayForVisionPrefill() ? "FFPA d512 vision-block overlay" : "FMHA CUSTOM_MASK");
419	    }
420	    else if (!mCanImplementFMHA && !mCanImplementFFPA && !mCanImplementXQA)
421	    {
422	        LOG_ERROR("Cannot implement AttentionPlugin configuration. SM: %d, HeadSize: %d, NumQHeads: %d, NumKVHeads: %d",
423	            mSMVersion, mHeadSize, mNumQHeads, mNumKVHeads);
424	        throw std::runtime_error("Cannot implement the AttentionPlugin configuration.");
425	    }
426	    else if (!mCanImplementFMHA)
427	    {
428	        if (mCanImplementFFPA)
429	        {
430	            LOG_INFO("AttentionPlugin: FMHA unsupported for headSize=%d, using FFPA for prefill%s.", mHeadSize,
431	                mCanImplementXQA ? " + XQA for decode" : "");
432	        }
433	        else
434	        {
435	            LOG_WARNING(
436	                "AttentionPlugin: no prefill kernel for headSize=%d; only decode (XQA) is supported.", mHeadSize);
437	        }
438	    }
439	}
440	
441	AttentionPlugin::AttentionPlugin(std::string const& name, PluginFieldCollection const* fc)
442	    : mLayerName(name)
443	    , mNumQHeads(parsePluginScalarField<int32_t>("num_q_heads", fc).value_or(0))
444	    , mNumKVHeads(parsePluginScalarField<int32_t>("num_kv_heads", fc).value_or(0))
445	    , mHeadSize(parsePluginScalarField<int32_t>("head_size", fc).value_or(0))
446	    , mAttentionScale(resolveAttentionScale(parsePluginScalarField<float>("attention_scale", fc), mHeadSize))
447	    , mEnableTreeAttention(parsePluginScalarField<int32_t>("enable_tree_attention", fc).value_or(0))
448	    , mEnableFp8KVCache(parsePluginScalarField<int32_t>("enable_fp8_kv_cache", fc).value_or(0))
449	    , mSlidingWindowSize(parsePluginScalarField<int32_t>("sliding_window_size", fc).value_or(-1))
450	{
451	    mEnableVisionBlockAttention = parsePluginScalarField<int32_t>("enable_vision_block_attention", fc).value_or(0);
452	    ELLM_CHECK(!(mEnableTreeAttention && mEnableVisionBlockAttention),
453	        "Tree attention and vision block attention are mutually exclusive.");
454	    ELLM_CHECK(!mEnableVisionBlockAttention || !mEnableFp8KVCache, "Vision block attention requires an FP16 KV cache.");
455	
456	    // Parse qkv_scales float array
457	    for (int32_t i = 0; i < fc->nbFields; ++i)
458	    {
459	        if (std::string("qkv_scales") == fc->fields[i].name)
460	        {
461	            auto const* data = static_cast<float const*>(fc->fields[i].data);
462	            mQkvScales.assign(data, data + fc->fields[i].length);
463	            break;
464	        }
465	    }
466	
467	    if (!mEnableFp8KVCache)
468	    {
469	        mQkvScales = {1.f, 1.f, 1.f};
470	    }
471	    else
472	    {
473	        ELLM_CHECK(mQkvScales.size() == 3,
474	            "FP8 KV cache enabled but qkv_scales missing or incomplete "
475	            "in plugin fields (expected 3). Re-export the model with QKV scales [q, k, v].");
476	    }
477	
478	    mSMVersion = getSMVersion();
479	    applyThorSMRenumberWAR(mSMVersion);
480	
481	    LOG_DEBUG("AttentionPlugin FMHA path: %s", mUseCuteDslFMHA ? "CuTe DSL FMHA" : "FMHA_v2");
482	
483	    mCanImplementFMHA = loadFMHAKernels(mUseCuteDslFMHA, mHeadSize, mSMVersion, mDataType, mSlidingWindowSize > 0);
484	
485	    // XQA decode kernels.
486	    bool const usePagedKVCache = false;
487	    mCanImplementXQA = DecoderXQARunner::canImplement(mNumQHeads, mNumKVHeads, mHeadSize, mSMVersion, mDataType,
488	        selectKvCacheDataType(mEnableFp8KVCache), usePagedKVCache);
489	    if (mCanImplementXQA)
490	    {
491	        DecoderXQARunner::loadDecodeXQAKernels(mSMVersion, mDataType, selectKvCacheDataType(mEnableFp8KVCache),
492	            /*useSpecDecodeKernels=*/true, usePagedKVCache);
493	    }
494	
495	    if (!mCanImplementFMHA)
496	    {
497	#ifdef CUTE_DSL_FFPA_ENABLED
498	        if (mHeadSize == 512 && CuteDslFFPARunner::canImplement(mHeadSize, mSMVersion, mNumQHeads, mNumKVHeads))
499	        {
500	            if (CuteDslFFPARunner::loadKernelModule())
501	            {
502	                mCanImplementFFPA = true;
503	            }
504	        }
505	#endif
506	    }
507	
508	    // Sliding d256-class vision prefill production path: FMHA_v2 CUSTOM_MASK,
509	    // discovered from the cubin metadata table.
510	    if (mEnableVisionBlockAttention)
511	    {
512	        mCanImplementCustomMaskFMHA = ContextFMHARunner::canImplement(mHeadSize, mSMVersion, mDataType,
513	                                          AttentionInputLayout::SEPARATE_Q_K_V, ContextAttentionMaskType::CUSTOM_MASK)
514	            && ContextFMHARunner::loadContextFMHAKernels(mSMVersion, mDataType);
515	
516	        enforceVisionBlockKernelSupport();
517	    }
518	}
