613	int32_t AttentionPlugin::getOutputShapes(DimsExprs const* inputs, [[maybe_unused]] int32_t nbInputs,
614	    DimsExprs const* /* shapeInputs */, int32_t /* nbShapeInputs */, DimsExprs* outputs,
615	    [[maybe_unused]] int32_t nbOutputs, IExprBuilder& exprBuilder) noexcept
616	{
617	    try
618	    {
619	        assert(nbOutputs == kNUM_REQUIRED_OUTPUTS);
620	        // Output[0] is attention result, has shape [B, S, Hq, D]. Refers to Q shape [B, S, Hq*D]
621	        outputs[kOUT_ATTENTION_IDX].nbDims = 4;
622	        outputs[kOUT_ATTENTION_IDX].d[0] = inputs[kIN_Q_IDX].d[0];
623	        outputs[kOUT_ATTENTION_IDX].d[1] = inputs[kIN_Q_IDX].d[1];
624	        outputs[kOUT_ATTENTION_IDX].d[2] = exprBuilder.constant(mNumQHeads);
625	        outputs[kOUT_ATTENTION_IDX].d[3] = exprBuilder.constant(mHeadSize);
626	
627	        // Output[1] is KVCache, same shape as input KV cache [B, 2, Hkv, Smax, D]
628	        outputs[kOUT_KV_CACHE_IDX].nbDims = 5;
629	        outputs[kOUT_KV_CACHE_IDX].d[0] = inputs[kIN_KV_CACHE_IDX].d[0];
630	        outputs[kOUT_KV_CACHE_IDX].d[1] = inputs[kIN_KV_CACHE_IDX].d[1];
631	        outputs[kOUT_KV_CACHE_IDX].d[2] = inputs[kIN_KV_CACHE_IDX].d[2];
632	        outputs[kOUT_KV_CACHE_IDX].d[3] = inputs[kIN_KV_CACHE_IDX].d[3];
633	        outputs[kOUT_KV_CACHE_IDX].d[4] = inputs[kIN_KV_CACHE_IDX].d[4];
634	
635	        return 0;
636	    }
637	    catch (std::exception const& e)
638	    {
639	        return -1;
640	    }
641	}
642	
643	bool AttentionPlugin::supportsFormatCombination(
644	    int32_t pos, DynamicPluginTensorDesc const* inOut, int32_t nbInputs, int32_t nbOutputs) noexcept
645	{
646	    // Support context/generation phase inputs:
647	    //      Q tensor (linear FP16) with shape [B, S, Hq, D]
648	    //      K tensor (linear FP16) with shape [B, S, Hkv, D]
649	    //      V tensor (linear FP16) with shape [B, S, Hkv, D]
650	    //      KV-cache tensor (linear FP16/FP8) with shape [B, 2, Hkv, Smax, D], here Smax is the kvcache capacity
651	    //      buffer.
652	    //      Real context length: [B] (a vector of scalars) with type int32_t.
653	    //      RoPE cos/sin cache: [B or 1, Smax, D] (a tensor of scalars) with type float.
654	    //            Rope CosSin can be ND vector depending on rope type.
655	    //      Start index of the KVCache [B, 0~1] (a vector of scalars) with type int32_t.
656	    //            0 length indicates there is no existing KVCache for inference.
657	    //      Optional tree attention mask: [B, S, S] (a tensor of scalars) with type int32_t.
658	    //      Optional tree attention position ids: [B, S] (a tensor of scalars) with type int32_t.
659	
660	    // Support context/generation phase outputs:
661	    //      attention result (linear FP16) with shape [B, S, Hq, D]
662	    //      KV-cache tensor, same as the above.
663	    auto checkQ = [this](PluginTensorDesc const& tensorDesc) {
664	        bool status{true};
665	        status &= tensorDesc.type == DataType::kHALF;
666	        status &= tensorDesc.format == TensorFormat::kLINEAR;
667	        status &= tensorDesc.dims.nbDims == 3;
668	        auto const tensorDim = tensorDesc.dims;
669	        if (status)
670	        {
671	            status &= tensorDim.d[2] == mNumQHeads * mHeadSize;
672	        }
673	        return status;
674	    };
675	
676	    auto checkKV = [this](PluginTensorDesc const& tensorDesc) {
677	        bool status{true};
678	        status &= tensorDesc.type == DataType::kHALF;
679	        status &= tensorDesc.format == TensorFormat::kLINEAR;
680	        status &= tensorDesc.dims.nbDims == 3;
681	        auto const tensorDim = tensorDesc.dims;
682	        if (status)
683	        {
684	            status &= tensorDim.d[2] == mNumKVHeads * mHeadSize;
685	        }
686	        return status;
687	    };
688	
689	    auto checkKVCache = [this](PluginTensorDesc const& tensorDesc) {
690	        bool status{true};
691	        // Support FP16 or FP8 storage;
692	        if (mEnableFp8KVCache)
693	        {
694	            status &= (tensorDesc.type == DataType::kFP8);
695	        }
696	        else
697	        {
698	            status &= (tensorDesc.type == DataType::kHALF);
699	        }
700	        status &= tensorDesc.format == TensorFormat::kLINEAR;
701	        status &= tensorDesc.dims.nbDims == 5;
702	        if (status)
703	        {
704	            auto const tensorDim = tensorDesc.dims;
705	            status &= tensorDim.d[1] == 2; // Specify K and V
706	            status &= tensorDim.d[2] == mNumKVHeads;
707	            status &= tensorDim.d[4] == mHeadSize;
708	        }
709	        return status;
710	    };
711	
712	    auto checkSequenceLen = [](PluginTensorDesc const& tensorDesc) {
713	        bool status{true};
714	        status &= tensorDesc.type == DataType::kINT32;
715	        status &= tensorDesc.format == TensorFormat::kLINEAR;
716	        status &= tensorDesc.dims.nbDims == 1;
717	        return status;
718	    };
719	
720	    auto checkPosEncodingCosSin = [this](PluginTensorDesc const& tensorDesc) {
721	        bool status{true};
722	        status &= tensorDesc.type == DataType::kFLOAT;
723	        status &= tensorDesc.format == TensorFormat::kLINEAR;
724	        status &= tensorDesc.dims.nbDims == 3;
725	        status &= tensorDesc.dims.d[2] <= mHeadSize;
726	        return status;
727	    };
728	
729	    auto checkAttentionMask = [](PluginTensorDesc const& tensorDesc) {
730	        bool status{true};
731	        status &= tensorDesc.type == DataType::kINT32;
732	        status &= tensorDesc.format == TensorFormat::kLINEAR;
733	        status &= tensorDesc.dims.nbDims == 3;
734	        return status;
735	    };
736	
737	    auto checkAttentionPosId = [](PluginTensorDesc const& tensorDesc) {
738	        bool status{true};
739	        status &= tensorDesc.type == DataType::kINT32;
740	        status &= tensorDesc.format == TensorFormat::kLINEAR;
741	        status &= tensorDesc.dims.nbDims == 2;
742	        return status;
743	    };
744	
745	    auto checkVisionBlockIds = [](PluginTensorDesc const& tensorDesc) {
746	        bool status{true};
747	        status &= tensorDesc.type == DataType::kINT32;
748	        status &= tensorDesc.format == TensorFormat::kLINEAR;
749	        status &= tensorDesc.dims.nbDims == 2;
750	        return status;
751	    };
752	
753	    auto checkKVCacheStartIdx = [](PluginTensorDesc const& tensorDesc) {
754	        bool status{true};
755	        status &= tensorDesc.type == DataType::kINT32;
756	        status &= tensorDesc.format == TensorFormat::kLINEAR;
757	        status &= tensorDesc.dims.nbDims == 1;
758	        return status;
759	    };
760	
761	    auto checkAttentionOutput = [this](PluginTensorDesc const& tensorDesc) {
762	        bool status{true};
763	        status &= tensorDesc.type == DataType::kHALF;
764	        status &= tensorDesc.format == TensorFormat::kLINEAR;
765	        status &= tensorDesc.dims.nbDims == 4;
766	        if (status)
767	        {
768	            auto const tensorDim = tensorDesc.dims;
769	            status &= tensorDim.d[2] == mNumQHeads;
770	            status &= tensorDim.d[3] == mHeadSize;
771	        }
772	        return status;
773	    };
774	
775	    int32_t const expectedNbInputs = kNUM_REQUIRED_INPUTS + (mEnableTreeAttention ? kNUM_TREE_ATTN_OPTIONAL_INPUTS : 0)
776	        + (mEnableVisionBlockAttention ? kNUM_VISION_BLOCK_OPTIONAL_INPUTS : 0);
777	    bool const checkNumIOs = nbInputs == expectedNbInputs && nbOutputs == kNUM_REQUIRED_OUTPUTS;
778	    if (!checkNumIOs)
779	    {
780	        LOG_ERROR(
781	            "Invalid number of inputs or outputs for the AttentionPlugin '%s'. Expected %d inputs and %d outputs, but "
782	            "got %d inputs and %d outputs.",
783	            mLayerName.c_str(), expectedNbInputs, kNUM_REQUIRED_OUTPUTS, nbInputs, nbOutputs);
784	        return false;
785	    }
786	
787	    bool result{true};
788	
789	    if (pos < nbInputs)
790	    {
791	        switch (pos)
792	        {
793	        case kIN_Q_IDX: result = checkQ(inOut[pos].desc); break;
794	        case kIN_K_IDX: result = checkKV(inOut[pos].desc); break;
795	        case kIN_V_IDX: result = checkKV(inOut[pos].desc); break;
796	        case kIN_KV_CACHE_IDX: result = checkKVCache(inOut[pos].desc); break;
797	        case kIN_CONTEXT_LENGTH_IDX: result = checkSequenceLen(inOut[pos].desc); break;
798	        case kIN_ROPE_COS_SIN_IDX: result = checkPosEncodingCosSin(inOut[pos].desc); break;
799	        case kIN_KV_CACHE_START_IDX: result = checkKVCacheStartIdx(inOut[pos].desc); break;
800	        default: break;
801	        }
802	
803	        // Handle optional inputs (tree attention mask/pos and FP8 scales) with dynamic ordering
804	        if (result && pos > kIN_KV_CACHE_START_IDX)
805	        {
806	            int32_t currentOptionalInputIdx = kIN_KV_CACHE_START_IDX + 1;
807	            if (mEnableTreeAttention)
808	            {
809	                if (pos == currentOptionalInputIdx)
810	                {
811	                    result = checkAttentionMask(inOut[pos].desc);
812	                }
813	                currentOptionalInputIdx++;
814	                if (pos == currentOptionalInputIdx)
815	                {
816	                    result = checkAttentionPosId(inOut[pos].desc);
817	                }
818	                currentOptionalInputIdx++;
819	            }
820	            if (mEnableVisionBlockAttention && pos == currentOptionalInputIdx)
821	            {
822	                result = checkVisionBlockIds(inOut[pos].desc);
823	            }
824	        }
825	    }
826	    else
827	    {
828	        int32_t outPos = pos - nbInputs;
829	        switch (outPos)
830	        {
831	        case kOUT_ATTENTION_IDX: result = checkAttentionOutput(inOut[pos].desc); break;
832	        case kOUT_KV_CACHE_IDX: result = checkKVCache(inOut[pos].desc); break;
833	        default: break;
834	        }
835	    }
836	
837	    return result;
838	}
