877	int32_t AttentionPlugin::enqueue(PluginTensorDesc const* inputDesc, PluginTensorDesc const* outputDesc,
878	    void const* const* inputs, void* const* outputs, void* workspace, cudaStream_t stream) noexcept
879	{
880	    // enqueue is noexcept: an exception escaping a kernel dispatch (e.g. a
881	    // missing-cubin check) would terminate the process. Turn it into a failed
882	    // enqueue instead.
883	    try
884	    {
885	        return enqueueImpl(inputDesc, outputDesc, inputs, outputs, workspace, stream);
886	    }
887	    catch (std::exception const& e)
888	    {
889	        LOG_ERROR("AttentionPlugin: enqueue failed: %s", e.what());
890	        return -1;
891	    }
892	    catch (...)
893	    {
894	        LOG_ERROR("AttentionPlugin: enqueue failed with a non-standard exception.");
895	        return -1;
896	    }
897	}
