899	int32_t AttentionPlugin::enqueueImpl(PluginTensorDesc const* inputDesc,
900	    [[maybe_unused]] PluginTensorDesc const* outputDesc, void const* const* inputs, void* const* outputs,
901	    void* workspace, cudaStream_t stream)
902	{
903	    // Construct non-owned tensor objects from I/O data pointers and shapes.
904	    // Q input in the graph will be in shape [B, S, Hq x D], for convenience,
905	    // we will use shape of [B, S, Hq, D] to represent the tensor.
906	    // K and V inputs are in shape [B, S, Hkv x D], represented as [B, S, Hkv, D].
907	    PluginTensorDesc const& qInputDesc = inputDesc[kIN_Q_IDX];
908	    PluginTensorDesc const& kInputDesc = inputDesc[kIN_K_IDX];
909	    PluginTensorDesc const& vInputDesc = inputDesc[kIN_V_IDX];
910	    int32_t const runtimeBatchSize = static_cast<int32_t>(qInputDesc.dims.d[0]);
911	    int32_t const runtimeSeqLen = static_cast<int32_t>(qInputDesc.dims.d[1]);
912	    int32_t const kvSeqLen = static_cast<int32_t>(kInputDesc.dims.d[1]);
913	    bool const sharedKV = (kvSeqLen == 0);
914	
915	    check::check(kInputDesc.dims.d[0] == runtimeBatchSize && vInputDesc.dims.d[0] == runtimeBatchSize,
916	        "Batch size must be consistent across Q/K/V inputs.");
917	    check::check(kInputDesc.dims.d[1] == vInputDesc.dims.d[1], "K and V sequence lengths must be consistent.");
918	    if (!sharedKV)
919	    {
920	        check::check(
921	            kvSeqLen == runtimeSeqLen, "K/V sequence length must equal Q sequence length when not in shared-KV mode.");
922	    }
923	    check::check(qInputDesc.dims.d[2] == mNumQHeads * mHeadSize, "Q input shape shall be consistent.");
924	    check::check(kInputDesc.dims.d[2] == mNumKVHeads * mHeadSize, "K input shape shall be consistent.");
925	    check::check(vInputDesc.dims.d[2] == mNumKVHeads * mHeadSize, "V input shape shall be consistent.");
926	
927	    rt::Tensor qInputTensor(const_cast<void*>(inputs[kIN_Q_IDX]),
928	        rt::Coords{runtimeBatchSize, runtimeSeqLen, mNumQHeads, mHeadSize}, rt::DeviceType::kGPU, qInputDesc.type);
929	    rt::Tensor kInputTensor(const_cast<void*>(inputs[kIN_K_IDX]),
930	        rt::Coords{runtimeBatchSize, kvSeqLen, mNumKVHeads, mHeadSize}, rt::DeviceType::kGPU, kInputDesc.type);
931	    rt::Tensor vInputTensor(const_cast<void*>(inputs[kIN_V_IDX]),
932	        rt::Coords{runtimeBatchSize, kvSeqLen, mNumKVHeads, mHeadSize}, rt::DeviceType::kGPU, vInputDesc.type);
933	
934	    PluginTensorDesc const& contextLengthInputDesc = inputDesc[kIN_CONTEXT_LENGTH_IDX];
935	    rt::Tensor const contextLengthTensor(const_cast<void*>(inputs[kIN_CONTEXT_LENGTH_IDX]),
936	        rt::Coords{contextLengthInputDesc.dims}, rt::DeviceType::kGPU, contextLengthInputDesc.type);
937	
938	    PluginTensorDesc const& posEncodingCosSinDesc = inputDesc[kIN_ROPE_COS_SIN_IDX];
939	    rt::Tensor const ropeCosSinTensor(const_cast<void*>(inputs[kIN_ROPE_COS_SIN_IDX]),
940	        rt::Coords{posEncodingCosSinDesc.dims}, rt::DeviceType::kGPU, posEncodingCosSinDesc.type);
941	
942	    PluginTensorDesc const& kvCacheStartIdxInputDesc = inputDesc[kIN_KV_CACHE_START_IDX];
943	    rt::Tensor const kvCacheStartIdxTensor(const_cast<void*>(inputs[kIN_KV_CACHE_START_IDX]),
944	        rt::Coords{kvCacheStartIdxInputDesc.dims}, rt::DeviceType::kGPU, kvCacheStartIdxInputDesc.type);
945	
946	    PluginTensorDesc const& attentionOutputDesc = outputDesc[kOUT_ATTENTION_IDX];
947	    rt::Tensor attentionOutputTensor(outputs[kOUT_ATTENTION_IDX], rt::Coords{attentionOutputDesc.dims},
948	        rt::DeviceType::kGPU, attentionOutputDesc.type);
949	
950	    // Construct the KV cache tensor from the past-KV input descriptor. Shared-KV
951	    // draft layers are read-only views of the target/base cache, so they must
952	    // read the input binding rather than the plugin's present-KV output. The
953	    // present-KV output is not consumed in shared-KV mode and must remain
954	    // unwritten by every shared-KV path below.
955	    PluginTensorDesc const& kvCacheInputDesc = inputDesc[kIN_KV_CACHE_IDX];
956	    rt::Tensor pastKVCacheTensor(const_cast<void*>(inputs[kIN_KV_CACHE_IDX]), rt::Coords{kvCacheInputDesc.dims},
957	        rt::DeviceType::kGPU, kvCacheInputDesc.type);
958	    rt::Tensor presentKVCacheTensor(
959	        outputs[kOUT_KV_CACHE_IDX], rt::Coords{kvCacheInputDesc.dims}, rt::DeviceType::kGPU, kvCacheInputDesc.type);
960	    rt::Tensor& kvCacheTensor = sharedKV ? pastKVCacheTensor : presentKVCacheTensor;
961	
962	    // Extract KV cache capacity from the runtime tensor shape.
963	    int32_t const kvCacheCapacity = static_cast<int32_t>(kvCacheInputDesc.dims.d[3]);
964	
965	    // Optional Inputs that are not used with Tree Attention enabled.
966	    rt::Tensor attentionMaskTensor{};
967	    rt::Tensor attentionPosIdTensor{};
968	    rt::Tensor visionBlockIdsTensor{};
969	    if (mEnableTreeAttention)
970	    {
971	        PluginTensorDesc const& attentionMaskInputDesc = inputDesc[kIN_OPTIONAL_ATTN_MASK_IDX];
972	        PluginTensorDesc const& attentionPosIdInputDesc = inputDesc[kIN_OPTIONAL_ATTN_POS_ID_IDX];
973	        attentionMaskTensor = rt::Tensor(const_cast<void*>(inputs[kIN_OPTIONAL_ATTN_MASK_IDX]),
974	            rt::Coords{attentionMaskInputDesc.dims}, rt::DeviceType::kGPU, attentionMaskInputDesc.type);
975	        attentionPosIdTensor = rt::Tensor(const_cast<void*>(inputs[kIN_OPTIONAL_ATTN_POS_ID_IDX]),
976	            rt::Coords{attentionPosIdInputDesc.dims}, rt::DeviceType::kGPU, attentionPosIdInputDesc.type);
977	    }
978	    else if (mEnableVisionBlockAttention)
979	    {
980	        PluginTensorDesc const& visionBlockIdsDesc = inputDesc[kIN_OPTIONAL_ATTN_MASK_IDX];
981	        visionBlockIdsTensor = rt::Tensor(const_cast<void*>(inputs[kIN_OPTIONAL_ATTN_MASK_IDX]),
982	            rt::Coords{visionBlockIdsDesc.dims}, rt::DeviceType::kGPU, visionBlockIdsDesc.type);
983	    }
984	    bool const useExplicitPositionIds = mEnableTreeAttention && !attentionPosIdTensor.isEmpty()
985	        && attentionPosIdTensor.getShape().getNumDims() == 2 && attentionPosIdTensor.getShape()[1] == runtimeSeqLen;
986	
987	    float const kScale = mQkvScales[1];
988	    float const vScale = mQkvScales[2];
989	
990	    // Determine the attention execution mode based on the input tensors.
991	    AttentionExecutionMode executionMode{};
992	    if (!mEnableTreeAttention)
993	    {
994	        executionMode = deduceModeVanilla(qInputTensor, kvCacheStartIdxTensor);
995	    }
996	    else
997	    {
998	        executionMode = deduceModeTreeAttention(qInputTensor, kvCacheStartIdxTensor, attentionPosIdTensor);
999	    }
1000	
1001	    // For invalid execution mode, log error and report error return value.
1002	    if (executionMode == AttentionExecutionMode::kINVALID)
1003	    {
1004	        LOG_ERROR("Invalid attention execution mode detected. Abort the AttentionPlugin enqueue() call.");
1005	        return 1;
1006	    }
1007	
1008	    auto* alignedWorkspacePtr = static_cast<std::byte*>(workspace);
1009	    if (alignedWorkspacePtr == nullptr
1010	        || reinterpret_cast<uintptr_t>(alignedWorkspacePtr) % static_cast<uintptr_t>(kDEVICE_ALIGNMENT) != 0)
1011	    {
1012	        LOG_ERROR("Workspace pointer is not aligned to device alignment granularity");
1013	        return 1;
1014	    }
1015	
1016	    // ==================== Prefill path ====================
1017	    // Dispatch order: vision-block attention first (FFPA d512 overlay or FMHA
1018	    // CUSTOM_MASK, early return), then sharedKV (early return), then own-KV.
1019	    // Within each: FMHA (standard), FFPA (headSize=512), or reject the
1020	    // prefill when neither kernel serves the head size.
1021	    if (executionMode == AttentionExecutionMode::kNORMAL_PREFILL
1022	        || executionMode == AttentionExecutionMode::kCHUNKED_PREFILL)
1023	    {
1024	        // No prefill backend can read an FP8 donor cache.
1025	        if (mEnableFp8KVCache && sharedKV)
1026	        {
1027	            LOG_ERROR("AttentionPlugin: shared-KV prefill cannot read an FP8 donor cache.");
1028	            return -1;
1029	        }
1030	        // Chunked prefill reads the cache back; only the CuTe DSL FMHA reads FP8.
1031	        // Normal prefill reads the FP16 K/V inputs and needs no FP8 kernel.
1032	        if (mEnableFp8KVCache && executionMode == AttentionExecutionMode::kCHUNKED_PREFILL
1033	            && !(mUseCuteDslFMHA && mCanImplementFMHA))
1034	        {
1035	            LOG_ERROR(
1036	                "AttentionPlugin: FP8 KV cache chunked prefill requires the CuTe DSL FMHA path "
1037	                "(SM 100/101/110); the FP16-only prefill kernels cannot read the FP8 cache on SM %d.",
1038	                mSMVersion);
1039	            return -1;
1040	        }
1041	
1042	        if (mEnableVisionBlockAttention)
1043	        {
1044	            if (executionMode != AttentionExecutionMode::kNORMAL_PREFILL || sharedKV)
1045	            {
1046	                LOG_ERROR(
1047	                    "AttentionPlugin: Gemma4 vision-block attention supports only normal prefill with owned KV "
1048	                    "(mode=%d, sharedKV=%d).",
1049	                    static_cast<int32_t>(executionMode), static_cast<int32_t>(sharedKV));
1050	                return 1;
1051	            }
1052	            if (visionBlockIdsTensor.getShape()[0] != runtimeBatchSize
1053	                || visionBlockIdsTensor.getShape()[1] != runtimeSeqLen)
1054	            {
1055	                LOG_ERROR(
1056	                    "AttentionPlugin: vision_block_ids must have shape [B,S] matching Q; got [%lld,%lld], "
1057	                    "expected [%d,%d].",
1058	                    static_cast<long long>(visionBlockIdsTensor.getShape()[0]),
1059	                    static_cast<long long>(visionBlockIdsTensor.getShape()[1]), runtimeBatchSize, runtimeSeqLen);
1060	                return 1;
1061	            }
1062	
1063	            // Keep K input unmodified: Gemma4 full-attention layers may alias
1064	            // V=K before RoPE. The cache receives roped K and the original V,
1065	            // and both vision prefill paths read K/V from that canonical
1066	            // cache layout.
1067	            kernel::launchApplyRopeWriteKV(ropeCosSinTensor, std::nullopt, qInputTensor, kInputTensor, vInputTensor,
1068	                kvCacheTensor, kScale, vScale, stream, false);
1069	
1070	#ifdef CUTE_DSL_FFPA_ENABLED
1071	            if (canUseFFPAOverlayForVisionPrefill())
1072	            {
1073	                // Production path for the full-causal d512 global layers: the
1074	                // FFPA vision-block overlay kernel with per-row [blockBegin,
1075	                // blockEnd] intervals expanded from vision_block_ids.
1076	                LOG_DEBUG(
1077	                    "AttentionPlugin: vision-block prefill via FFPA d512 overlay (B=%d, S=%d, Hq=%d, Hkv=%d, cap=%d)",
1078	                    runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads, kvCacheCapacity);
1079	
1080	                rt::Tensor cuQSeqLensTensor
1081	                    = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1082	                rt::Tensor cuKVSeqLensTensor
1083	                    = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1084	                rt::Tensor kvCacheEndIdxsTensor
1085	                    = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize}, DataType::kINT32);
1086	                rt::Tensor paddedCuKVSeqLensTensor
1087	                    = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1088	                kernel::calCuQCuKVSeqLensAndKVEndIdxs(contextLengthTensor, kvCacheStartIdxTensor, cuQSeqLensTensor,
1089	                    cuKVSeqLensTensor, kvCacheEndIdxsTensor, paddedCuKVSeqLensTensor, runtimeSeqLen, stream);
1090	
1091	                // Expand vision_block_ids into per-position block intervals
1092	                // (-1/-1 sentinel for text and padding positions).
1093	                rt::Tensor blockBeginTensor = assignTensorFromWorkspace(
1094	                    alignedWorkspacePtr, {runtimeBatchSize, runtimeSeqLen}, DataType::kINT32);
1095	                rt::Tensor blockEndTensor = assignTensorFromWorkspace(
1096	                    alignedWorkspacePtr, {runtimeBatchSize, runtimeSeqLen}, DataType::kINT32);
1097	                kernel::launchBuildVisionBlockRanges(visionBlockIdsTensor.dataPointer<int32_t>(),
1098	                    contextLengthTensor.dataPointer<int32_t>(), blockBeginTensor.dataPointer<int32_t>(),
1099	                    blockEndTensor.dataPointer<int32_t>(), runtimeBatchSize, runtimeSeqLen, stream);
1100	
1101	                // Read K/V back from the just-updated cache (roped K, original
1102	                // V — required because V may alias K on the K=V layers).
1103	                // Compact deinterleave (first runtimeSeqLen tokens) keeps the
1104	                // physical batch stride at runtimeSeqLen; the logical KV
1105	                // length per batch is the same as the Q length (normal
1106	                // prefill, bottom-right offset 0), so cuQSeqLens bounds both
1107	                // sides.
1108	                auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1109	                    mNumKVHeads, kvCacheCapacity, mHeadSize, runtimeSeqLen, stream);
1110	                CuteDslFFPAParams ffpaParams{};
1111	                ffpaParams.q = qInputTensor.dataPointer<half>();
1112	                ffpaParams.k = kSplit.dataPointer<half>();
1113	                ffpaParams.v = vSplit.dataPointer<half>();
1114	                ffpaParams.o = attentionOutputTensor.dataPointer<half>();
1115	                ffpaParams.cuSeqLenQ = cuQSeqLensTensor.dataPointer<int32_t>();
1116	                ffpaParams.cuSeqLenK = cuQSeqLensTensor.dataPointer<int32_t>();
1117	                ffpaParams.blockBegin = blockBeginTensor.dataPointer<int32_t>();
1118	                ffpaParams.blockEnd = blockEndTensor.dataPointer<int32_t>();
1119	                ffpaParams.batchSize = runtimeBatchSize;
1120	                ffpaParams.seqlenQ = runtimeSeqLen;
1121	                ffpaParams.seqlenK = runtimeSeqLen;
1122	                ffpaParams.numQHeads = mNumQHeads;
1123	                ffpaParams.numKVHeads = mNumKVHeads;
1124	                ffpaParams.headDim = mHeadSize;
1125	                ffpaParams.softmaxScale = mAttentionScale;
1126	                CuteDslFFPARunner::run(ffpaParams, stream);
1127	                return 0;
1128	            }
1129	#endif
1130	
1131	            // Production path for the sliding d256-class layers: FMHA_v2 with
1132	            // ContextAttentionMaskType::CUSTOM_MASK.  The sliding-causal OR
1133	            // same-vision-block predicate is packed into the FMHA bitmask by
1134	            // launchBuildVisionPackedMask, so the kernel needs no window
1135	            // parameter.  Cubin availability is a hard construction-time
1136	            // requirement (enforceVisionBlockKernelSupport); only the exact
1137	            // per-sequence-length kernel (tiled vs non-tiled) is probed here.
1138	            auto fmhaRunner = ContextFMHARunner(mDataType, runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads,
1139	                mHeadSize, mSMVersion, AttentionInputLayout::SEPARATE_Q_K_V, ContextAttentionMaskType::CUSTOM_MASK);
1140	            if (!fmhaRunner.isKernelAvailable())
1141	            {
1142	                LOG_ERROR(
1143	                    "AttentionPlugin: no FMHA CUSTOM_MASK kernel for S=%d (headSize=%d, SM=%d); vision-block "
1144	                    "prefill has no fallback path.",
1145	                    runtimeSeqLen, mHeadSize, mSMVersion);
1146	                return 1;
1147	            }
1148	
1149	            LOG_DEBUG(
1150	                "AttentionPlugin: vision-block prefill via FMHA CUSTOM_MASK (B=%d, S=%d, Hq=%d, Hkv=%d, "
1151	                "window=%d)",
1152	                runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads, mSlidingWindowSize);
1153	
1154	            rt::Tensor cuQSeqLensTensor
1155	                = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1156	            rt::Tensor cuKVSeqLensTensor
1157	                = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1158	            rt::Tensor kvCacheEndIdxsTensor
1159	                = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize}, DataType::kINT32);
1160	            rt::Tensor paddedCuKVSeqLensTensor
1161	                = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1162	            kernel::calCuQCuKVSeqLensAndKVEndIdxs(contextLengthTensor, kvCacheStartIdxTensor, cuQSeqLensTensor,
1163	                cuKVSeqLensTensor, kvCacheEndIdxsTensor, paddedCuKVSeqLensTensor, runtimeSeqLen, stream);
1164	
1165	            // Pack the vision-block mask into the FMHA CUSTOM_MASK bit
1166	            // layout (sliding window folded into the bits).
1167	            int64_t const packedMaskWords
1168	                = kernel::getPackedMaskSizeInWords(runtimeBatchSize, runtimeSeqLen, runtimeSeqLen);
1169	            rt::Tensor packedMaskTensor
1170	                = assignTensorFromWorkspace(alignedWorkspacePtr, {packedMaskWords}, DataType::kINT32);
1171	            rt::Tensor cuMaskRowsTensor
1172	                = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1173	            kernel::launchBuildVisionPackedMask(visionBlockIdsTensor.dataPointer<int32_t>(),
1174	                contextLengthTensor.dataPointer<int32_t>(),
1175	                reinterpret_cast<uint32_t*>(packedMaskTensor.dataPointer<int32_t>()),
1176	                cuMaskRowsTensor.dataPointer<int32_t>(), runtimeBatchSize, runtimeSeqLen, mSlidingWindowSize, stream);
1177	
1178	            // Read K/V back from the just-updated cache (roped K,
1179	            // original V — required because V may alias K on the K=V
1180	            // layers).  Compact deinterleave keeps the physical batch
1181	            // stride at runtimeSeqLen, matching s_kv below.
1182	            auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1183	                mNumKVHeads, kvCacheCapacity, mHeadSize, runtimeSeqLen, stream);
1184	
1185	            FusedMultiheadAttentionParamsV2 params{};
1186	            fmhaRunner.setupParams(params, mAttentionScale);
1187	            params.s_kv = runtimeSeqLen;
1188	            params.q_ptr = qInputTensor.dataPointer<half>();
1189	            params.k_ptr = kSplit.dataPointer<half>();
1190	            params.v_ptr = vSplit.dataPointer<half>();
1191	            params.o_ptr = attentionOutputTensor.dataPointer<half>();
1192	            params.cu_q_seqlens = cuQSeqLensTensor.dataPointer<int32_t>();
1193	            params.cu_kv_seqlens = cuQSeqLensTensor.dataPointer<int32_t>();
1194	            params.cu_mask_rows = cuMaskRowsTensor.dataPointer<int32_t>();
1195	            params.packed_mask_ptr = packedMaskTensor.rawPointer();
1196	            params.packed_mask_stride_in_bytes = kernel::getPackedMaskRowStrideInBytes(runtimeSeqLen);
1197	            fmhaRunner.dispatchFMHAKernel(params, stream);
1198	            return 0;
1199	        }
1200	
1201	        // Allocate workspace tensors for cumulative sequence lengths.
1202	        rt::Tensor cuQSeqLensTensor
1203	            = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1204	
1205	        rt::Tensor cuKVSeqLensTensor
1206	            = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1207	        rt::Tensor kvCacheEndIdxsTensor
1208	            = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize}, DataType::kINT32);
1209	
1210	        // Padded cu_kv_seqlens for CuTe DSL FMHA bottom_right_align (see utilKernels.h for details).
1211	        rt::Tensor paddedCuKVSeqLensTensor
1212	            = assignTensorFromWorkspace(alignedWorkspacePtr, {runtimeBatchSize + 1}, DataType::kINT32);
1213	        kernel::calCuQCuKVSeqLensAndKVEndIdxs(contextLengthTensor, kvCacheStartIdxTensor, cuQSeqLensTensor,
1214	            cuKVSeqLensTensor, kvCacheEndIdxsTensor, paddedCuKVSeqLensTensor, runtimeSeqLen, stream);
1215	
1216	        if (sharedKV)
1217	        {
1218	            if (useExplicitPositionIds)
1219	            {
1220	                kernel::launchApplyRopeQOnlyTreeDecoding(ropeCosSinTensor, attentionPosIdTensor, qInputTensor, stream);
1221	            }
1222	            else
1223	            {
1224	                kernel::launchApplyRopeQOnly(ropeCosSinTensor, kvCacheEndIdxsTensor, qInputTensor, stream);
1225	            }
1226	
1227	            // Shared-KV without FMHA cubins: FFPA for headSize=512, reject any
1228	            // other head size.
1229	            if (!mCanImplementFMHA)
1230	            {
1231	#ifdef CUTE_DSL_FFPA_ENABLED
1232	                if (!mCanImplementFFPA)
1233	                {
1234	                    LOG_ERROR("AttentionPlugin: no prefill kernel for headSize=%d (FMHA unsupported%s).", mHeadSize,
1235	                        mHeadSize == 512 ? ", FFPA module failed to load" : "; FFPA serves headSize=512 only");
1236	                    return -1;
1237	                }
1238	
1239	                LOG_DEBUG(
1240	                    "AttentionPlugin: headSize=512 shared-KV prefill via FFPA native GQA "
1241	                    "(B=%d, S=%d, Hq=%d, Hkv=%d, D=%d, cap=%d)",
1242	                    runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads, mHeadSize, kvCacheCapacity);
1243	
1244	                // Per-batch cu_seqlens bound the logical lengths inside the kernel
1245	                // Ragged padding keys/rows are masked and the boundary
1246	                // tile is zero-filled, so no output zeroing WAR is needed.
1247	                if (executionMode == AttentionExecutionMode::kCHUNKED_PREFILL)
1248	                {
1249	                    // Chunked prefill: the Q chunk attends the donor cache prefix as
1250	                    // well, so deinterleave the full capacity and let the per-batch
1251	                    // cuKVSeqLens (prefix + chunk) drive the bottom-right causal
1252	                    // offset inside the kernel.
1253	                    auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1254	                        mNumKVHeads, kvCacheCapacity, mHeadSize, 0, stream);
1255	                    dispatchFFPAKernel(qInputTensor.dataPointer<half>(), kSplit.dataPointer<half>(),
1256	                        vSplit.dataPointer<half>(), attentionOutputTensor.dataPointer<half>(),
1257	                        cuQSeqLensTensor.dataPointer<int32_t>(), cuKVSeqLensTensor.dataPointer<int32_t>(),
1258	                        runtimeBatchSize, runtimeSeqLen, kvCacheCapacity, stream);
1259	                }
1260	                else
1261	                {
1262	                    // Normal prefill: compact deinterleave (first runtimeSeqLen tokens)
1263	                    // keeps the physical stride at runtimeSeqLen; the logical per-batch
1264	                    // lengths (cuKVSeqLens == cuQSeqLens, offset 0) mask ragged padding.
1265	                    auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1266	                        mNumKVHeads, kvCacheCapacity, mHeadSize, runtimeSeqLen, stream);
1267	                    dispatchFFPAKernel(qInputTensor.dataPointer<half>(), kSplit.dataPointer<half>(),
1268	                        vSplit.dataPointer<half>(), attentionOutputTensor.dataPointer<half>(),
1269	                        cuQSeqLensTensor.dataPointer<int32_t>(), cuKVSeqLensTensor.dataPointer<int32_t>(),
1270	                        runtimeBatchSize, runtimeSeqLen, runtimeSeqLen, stream);
1271	                }
1272	#else
1273	                LOG_ERROR(
1274	                    "AttentionPlugin: no prefill kernel for headSize=%d shared-KV prefill (FMHA unsupported, "
1275	                    "built without CUTE_DSL_FFPA_ENABLED).",
1276	                    mHeadSize);
1277	                return -1;
1278	#endif
1279	                return 0;
1280	            }
1281	
1282	            // Run FMHA reading from the donor's KV cache (bound to this layer's KV cache input).
1283	#ifdef CUTE_DSL_FMHA_ENABLED
1284	            if (mUseCuteDslFMHA)
1285	            {
1286	                // CuTe DSL FMHA reads interleaved KV cache natively.
1287	                // windowSizeLeft excludes the query itself; sliding_window_size counts it
1288	                // (last W keys, the XQA/HF convention), so pass W - 1.
1289	                int32_t const slidingWindow = mSlidingWindowSize > 0 ? mSlidingWindowSize - 1 : INT_MAX;
1290	                CuteDslFMHARunner runner(
1291	                    mNumQHeads, mNumKVHeads, mHeadSize, runtimeBatchSize, runtimeSeqLen, kvCacheCapacity);
1292	                runner.run(qInputTensor.dataPointer<half>(),        // Q  [b, s_q, h_q, d]
1293	                    kvCacheTensor.dataPointer<half>(),              // KV [b, 2, h_k, cap, d] (donor's cache)
1294	                    attentionOutputTensor.dataPointer<half>(),      // O  [b, s_q, h_q, d]
1295	                    paddedCuKVSeqLensTensor.dataPointer<int32_t>(), // cu_kv_seqlens [b+1]
1296	                    stream, mAttentionScale, slidingWindow);
1297	            }
1298	            else
1299	#endif
1300	            {
1301	                auto fmhaRunner = ContextFMHARunner(mDataType, runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads,
1302	                    mHeadSize, mSMVersion, AttentionInputLayout::SEPARATE_Q_K_V,
1303	                    mSlidingWindowSize > 0 ? ContextAttentionMaskType::SLIDING_OR_CHUNKED_CAUSAL
1304	                                           : ContextAttentionMaskType::CAUSAL);
1305	                FusedMultiheadAttentionParamsV2 params{};
1306	                fmhaRunner.setupParams(params, mAttentionScale);
1307	                if (mSlidingWindowSize > 0)
1308	                {
1309	                    params.sliding_window_size = mSlidingWindowSize;
1310	                }
1311	                params.cu_q_seqlens = cuQSeqLensTensor.dataPointer<int32_t>();
1312	
1313	                // Normal prefill: compact deinterleave (seqLen tokens) so FMHA_v2's
1314	                // s_kv-derived batch stride matches the physical layout.
1315	                // Chunked prefill: full deinterleave, s_kv = kvCacheCapacity.
1316	                bool const compact = (executionMode == AttentionExecutionMode::kNORMAL_PREFILL);
1317	                int32_t const seqLen = compact ? runtimeSeqLen : 0;
1318	                auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1319	                    mNumKVHeads, kvCacheCapacity, mHeadSize, seqLen, stream);
1320	
1321	                params.s_kv = compact ? runtimeSeqLen : kvCacheCapacity;
1322	                params.q_ptr = qInputTensor.dataPointer<half>();
1323	                params.k_ptr = kSplit.dataPointer<half>();
1324	                params.v_ptr = vSplit.dataPointer<half>();
1325	                params.cu_kv_seqlens = cuKVSeqLensTensor.dataPointer<int32_t>();
1326	                params.o_ptr = attentionOutputTensor.dataPointer<half>();
1327	                fmhaRunner.dispatchFMHAKernel(params, stream);
1328	            }
1329	            return 0;
1330	        }
1331	
1332	        // --- Own KV prefill: RoPE Q+K, write K/V to cache, then run attention kernel ---
1333	
1334	        // Own-KV without FMHA cubins: FFPA for headSize=512, reject any other
1335	        // head size.
1336	        if (!mCanImplementFMHA)
1337	        {
1338	            // headSize=512 prefill: apply RoPE, write K/V to cache, then use FFPA.
1339	            kernel::launchApplyRopeWriteKV(ropeCosSinTensor, kvCacheEndIdxsTensor, qInputTensor, kInputTensor,
1340	                vInputTensor, kvCacheTensor, kScale, vScale, stream, true);
1341	
1342	#ifdef CUTE_DSL_FFPA_ENABLED
1343	            if (!mCanImplementFFPA)
1344	            {
1345	                LOG_ERROR("AttentionPlugin: no prefill kernel for headSize=%d (FMHA unsupported%s).", mHeadSize,
1346	                    mHeadSize == 512 ? ", FFPA module failed to load" : "; FFPA serves headSize=512 only");
1347	                return -1;
1348	            }
1349	
1350	            // Use FFPA d512 causal kernel with native GQA support (no K/V expansion needed).
1351	            LOG_DEBUG(
1352	                "AttentionPlugin: headSize=512 own-KV prefill via FFPA native GQA "
1353	                "(B=%d, S=%d, Hq=%d, Hkv=%d, D=%d)",
1354	                runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads, mHeadSize);
1355	
1356	            if (executionMode == AttentionExecutionMode::kCHUNKED_PREFILL)
1357	            {
1358	                // Chunked prefill: the Q chunk must also attend the KV-cache prefix, so
1359	                // read K/V back from the just-updated cache.  Per-batch cuKVSeqLens
1360	                // (prefix + chunk) drive the bottom-right causal offset inside the kernel.
1361	                auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1362	                    mNumKVHeads, kvCacheCapacity, mHeadSize, 0, stream);
1363	                dispatchFFPAKernel(qInputTensor.dataPointer<half>(), kSplit.dataPointer<half>(),
1364	                    vSplit.dataPointer<half>(), attentionOutputTensor.dataPointer<half>(),
1365	                    cuQSeqLensTensor.dataPointer<int32_t>(), cuKVSeqLensTensor.dataPointer<int32_t>(), runtimeBatchSize,
1366	                    runtimeSeqLen, kvCacheCapacity, stream);
1367	            }
1368	            else
1369	            {
1370	                // Normal prefill: K/V inputs are the current (right-padded) sequences, so
1371	                // per-batch Q and KV logical lengths coincide (offset 0) — pass cuQSeqLens
1372	                // for both and ragged padding rows/keys are masked.
1373	                dispatchFFPAKernel(qInputTensor.dataPointer<half>(), kInputTensor.dataPointer<half>(),
1374	                    vInputTensor.dataPointer<half>(), attentionOutputTensor.dataPointer<half>(),
1375	                    cuQSeqLensTensor.dataPointer<int32_t>(), cuQSeqLensTensor.dataPointer<int32_t>(), runtimeBatchSize,
1376	                    runtimeSeqLen, runtimeSeqLen, stream);
1377	            }
1378	#else
1379	            LOG_ERROR(
1380	                "AttentionPlugin: no prefill kernel for headSize=%d own-KV prefill (FMHA unsupported, built "
1381	                "without CUTE_DSL_FFPA_ENABLED).",
1382	                mHeadSize);
1383	            return -1;
1384	#endif
1385	        }
1386	        else
1387	        {
1388	#ifdef CUTE_DSL_FMHA_ENABLED
1389	            if (mUseCuteDslFMHA)
1390	            {
1391	                float const qScale = mQkvScales[0];
1392	                // windowSizeLeft excludes the query itself; sliding_window_size counts it
1393	                // (last W keys, the XQA/HF convention), so pass W - 1.
1394	                int32_t const slidingWindow = mSlidingWindowSize > 0 ? mSlidingWindowSize - 1 : INT_MAX;
1395	
1396	                CuteDslFMHARunner runner(
1397	                    mNumQHeads, mNumKVHeads, mHeadSize, runtimeBatchSize, runtimeSeqLen, kvCacheCapacity);
1398	
1399	                if (mEnableFp8KVCache)
1400	                {
1401	                    // FP8 Q workspace: RoPE kernel quantizes roped Q to FP8 using calibrated qScale.
1402	                    rt::Tensor fp8QTensor = assignTensorFromWorkspace(
1403	                        alignedWorkspacePtr, {runtimeBatchSize, runtimeSeqLen, mNumQHeads, mHeadSize}, DataType::kFP8);
1404	
1405	                    // Single kernel: RoPE Q → FP8 output, RoPE K + write FP8 K/V to cache.
1406	                    kernel::launchApplyRopeWriteKVSplitQKV(ropeCosSinTensor, kvCacheEndIdxsTensor, qInputTensor,
1407	                        kInputTensor, vInputTensor, kvCacheTensor, kScale, vScale, stream, fp8QTensor.rawPointer(),
1408	                        qScale);
1409	
1410	                    runner.run(fp8QTensor.rawPointer(),                 // Q  [b, s_q, h_q, d] FP8
1411	                        kvCacheTensor.rawPointer(),                     // KV [b, 2, h_k, cap, d] FP8
1412	                        attentionOutputTensor.dataPointer<half>(),      // O  [b, s_q, h_q, d] FP16
1413	                        paddedCuKVSeqLensTensor.dataPointer<int32_t>(), // cu_kv_seqlens [b+1]
1414	                        stream, mAttentionScale, slidingWindow, /*fp8Input=*/true, qScale, kScale, vScale);
1415	                }
1416	                else
1417	                {
1418	                    // FP16 path: RoPE Q in-place, write FP16 K/V to cache.
1419	                    kernel::launchApplyRopeWriteKVSplitQKV(ropeCosSinTensor, kvCacheEndIdxsTensor, qInputTensor,
1420	                        kInputTensor, vInputTensor, kvCacheTensor, kScale, vScale, stream);
1421	
1422	                    runner.run(qInputTensor.dataPointer<half>(),        // Q  [b, s_q, h_q, d]
1423	                        kvCacheTensor.dataPointer<half>(),              // KV [b, 2, h_k, cap, d]
1424	                        attentionOutputTensor.dataPointer<half>(),      // O  [b, s_q, h_q, d]
1425	                        paddedCuKVSeqLensTensor.dataPointer<int32_t>(), // cu_kv_seqlens [b+1]
1426	                        stream, mAttentionScale, slidingWindow);
1427	                }
1428	            }
1429	            else
1430	#endif
1431	            {
1432	                auto fmhaRunner = ContextFMHARunner(mDataType, runtimeBatchSize, runtimeSeqLen, mNumQHeads, mNumKVHeads,
1433	                    mHeadSize, mSMVersion, AttentionInputLayout::SEPARATE_Q_K_V,
1434	                    mSlidingWindowSize > 0 ? ContextAttentionMaskType::SLIDING_OR_CHUNKED_CAUSAL
1435	                                           : ContextAttentionMaskType::CAUSAL);
1436	                FusedMultiheadAttentionParamsV2 params{};
1437	                fmhaRunner.setupParams(params, mAttentionScale);
1438	                if (mSlidingWindowSize > 0)
1439	                {
1440	                    params.sliding_window_size = mSlidingWindowSize;
1441	                }
1442	                params.cu_q_seqlens = cuQSeqLensTensor.dataPointer<int32_t>();
1443	
1444	                if (executionMode == AttentionExecutionMode::kCHUNKED_PREFILL)
1445	                {
1446	                    // kvCache: [b, 2, hkv, s, d] -> split K [b, s, hkv, d] + V [b, s, hkv, d]
1447	                    kernel::launchApplyRopeWriteKV(ropeCosSinTensor, kvCacheEndIdxsTensor, qInputTensor, kInputTensor,
1448	                        vInputTensor, kvCacheTensor, kScale, vScale, stream, false);
1449	
1450	                    auto [kSplit, vSplit] = deinterleaveKVCache(kvCacheTensor, alignedWorkspacePtr, runtimeBatchSize,
1451	                        mNumKVHeads, kvCacheCapacity, mHeadSize, 0, stream);
1452	
1453	                    // Set device ptr for FMHA kernel.
1454	                    params.s_kv = kvCacheCapacity;
1455	                    params.q_ptr = qInputTensor.dataPointer<half>();
1456	                    params.k_ptr = kSplit.dataPointer<half>();
1457	                    params.v_ptr = vSplit.dataPointer<half>();
1458	                    params.cu_kv_seqlens = cuKVSeqLensTensor.dataPointer<int32_t>();
1459	                    params.o_ptr = attentionOutputTensor.dataPointer<half>();
1460	                }
1461	                else
1462	                { // SEPARATE_Q_K_V
1463	                    kernel::launchApplyRopeWriteKV(ropeCosSinTensor, std::nullopt, qInputTensor, kInputTensor,
1464	                        vInputTensor, kvCacheTensor, kScale, vScale, stream, true);
1465	
1466	                    params.s_kv = runtimeSeqLen;
1467	                    params.q_ptr = qInputTensor.dataPointer<half>();
1468	                    params.k_ptr = kInputTensor.dataPointer<half>();
1469	                    params.v_ptr = vInputTensor.dataPointer<half>();
1470	                    params.cu_kv_seqlens = cuQSeqLensTensor.dataPointer<int32_t>();
1471	                    params.o_ptr = attentionOutputTensor.dataPointer<half>();
1472	                }
1473	
1474	                // Dispatch FMHA kernel
1475	                fmhaRunner.dispatchFMHAKernel(params, stream);
1476	            }
1477	        } // end mCanImplementFMHA
1478	    }
1479	    else
1480	    {
1481	        // Apply RoPE and (optionally) write K/V to cache.
1482	        // Shared KV: RoPE Q only, skip KV write (donor's cache is already populated).
1483	        // Non-shared: RoPE Q+K, write K/V to cache.
1484	        if (executionMode == AttentionExecutionMode::kTREE_DECODING)
1485	        {
1486	            if (sharedKV)
1487	            {
1488	                kernel::launchApplyRopeQOnlyTreeDecoding(ropeCosSinTensor, attentionPosIdTensor, qInputTensor, stream);
1489	            }
1490	            else
1491	            {
1492	                kernel::launchApplyRopeWriteKVTreeDecoding(ropeCosSinTensor, contextLengthTensor, attentionPosIdTensor,
1493	                    qInputTensor, kInputTensor, vInputTensor, kvCacheTensor, kScale, vScale, stream);
1494	            }
1495	        }
1496	        else
1497	        {
1498	            if (sharedKV)
1499	            {
1500	                if (useExplicitPositionIds)
1501	                {
1502	                    kernel::launchApplyRopeQOnlyTreeDecoding(
1503	                        ropeCosSinTensor, attentionPosIdTensor, qInputTensor, stream);
1504	                }
1505	                else
1506	                {
1507	                    kernel::launchApplyRopeQOnly(ropeCosSinTensor, contextLengthTensor, qInputTensor, stream);
1508	                }
1509	            }
1510	            else
1511	            {
1512	                kernel::launchApplyRopeWriteKV(ropeCosSinTensor, contextLengthTensor, qInputTensor, kInputTensor,
1513	                    vInputTensor, kvCacheTensor, kScale, vScale, stream, false);
1514	            }
1515	        }
1516	
1517	        // Vision-block decode goes to XQA (a hard construction-time
1518	        // requirement): newly generated tokens are text, so decode is pure
1519	        // causal/sliding — identical masking to the non-vision path.
1520	        // Cache-state parity: the vision prefill paths write the cache with
1521	        // launchApplyRopeWriteKV (roped K + original V in the canonical
1522	        // [B, 2, Hkv, cap, D] layout) and the decode RoPE above appended the
1523	        // new token the same way as the non-vision path, so XQA reads exactly
1524	        // the cache state it would see without vision.
1525	
1526	        // XQA decode kernel dispatch.
1527	        auto xqaRunner = DecoderXQARunner(mDataType, selectKvCacheDataType(mEnableFp8KVCache), runtimeBatchSize,
1528	            mNumQHeads, mNumKVHeads, mHeadSize, mSMVersion);
1529	        XQALaunchParams params = xqaRunner.initXQAParams();
1530	        params.attentionScale = mAttentionScale;
1531	        if (mEnableFp8KVCache)
1532	        {
1533	            params.kScale = kScale;
1534	            params.vScale = vScale;
1535	        }
1536	        params.output = attentionOutputTensor.dataPointer<half>();
1537	        params.qInputPtr = qInputTensor.dataPointer<half>();
1538	        params.kvCache.data = kvCacheTensor.rawPointer();
1539	        params.kvCache.sequence_lengths = contextLengthTensor.dataPointer<int32_t>();
1540	        params.kvCache.capacity = kvCacheCapacity;
1541	        params.slidingWinSize = mSlidingWindowSize > 0 ? static_cast<uint32_t>(mSlidingWindowSize) : 0U;
1542	        if (executionMode == AttentionExecutionMode::kTREE_DECODING)
1543	        {
1544	            // Execute tree attention decoding.
1545	            params.treeAttnMask = attentionMaskTensor.dataPointer<int32_t>();
1546	            params.qSeqLen = runtimeSeqLen;
1547	            xqaRunner.dispatchSpecDecodeXQAKernel(params, stream);
1548	        }
1549	        else
1550	        {
1551	            // Execute vanilla decoding.
1552	            xqaRunner.dispatchXQAKernel(params, stream);
1553	        }
1554	    }
1555	    return 0;
1556	}
