1569	PluginFieldCollection const* AttentionPlugin::getFieldsToSerialize() noexcept
1570	{
1571	    mDataToSerialize.clear();
1572	    mDataToSerialize.emplace_back("num_q_heads", &mNumQHeads, PluginFieldType::kINT32, 1);
1573	    mDataToSerialize.emplace_back("num_kv_heads", &mNumKVHeads, PluginFieldType::kINT32, 1);
1574	    mDataToSerialize.emplace_back("head_size", &mHeadSize, PluginFieldType::kINT32, 1);
1575	    mDataToSerialize.emplace_back("attention_scale", &mAttentionScale, PluginFieldType::kFLOAT32, 1);
1576	    mDataToSerialize.emplace_back("enable_tree_attention", &mEnableTreeAttention, PluginFieldType::kINT32, 1);
1577	    mDataToSerialize.emplace_back("enable_fp8_kv_cache", &mEnableFp8KVCache, PluginFieldType::kINT32, 1);
1578	    mDataToSerialize.emplace_back(
1579	        "enable_vision_block_attention", &mEnableVisionBlockAttention, PluginFieldType::kINT32, 1);
1580	    mDataToSerialize.emplace_back("sliding_window_size", &mSlidingWindowSize, PluginFieldType::kINT32, 1);
1581	    mDataToSerialize.emplace_back(
1582	        "qkv_scales", mQkvScales.data(), PluginFieldType::kFLOAT32, static_cast<int32_t>(mQkvScales.size()));
1583	    mFCToSerialize.nbFields = static_cast<int32_t>(mDataToSerialize.size());
1584	    mFCToSerialize.fields = mDataToSerialize.data();
1585	    return &mFCToSerialize;
1586	}
