1592	AttentionPluginCreator::AttentionPluginCreator()
1593	{
1594	    static std::mutex sMutex;
1595	    std::lock_guard<std::mutex> lock(sMutex);
1596	
1597	    mPluginAttributes.clear();
1598	    mPluginAttributes.emplace_back(PluginField("num_q_heads", nullptr, PluginFieldType::kINT32, 1));
1599	    mPluginAttributes.emplace_back(PluginField("num_kv_heads", nullptr, PluginFieldType::kINT32, 1));
1600	    mPluginAttributes.emplace_back(PluginField("head_size", nullptr, PluginFieldType::kINT32, 1));
1601	    mPluginAttributes.emplace_back(PluginField("attention_scale", nullptr, PluginFieldType::kFLOAT32, 0));
1602	    // Make enable_fp8_kv_cache optional with default value 0 (disable by default)
1603	    mPluginAttributes.emplace_back(PluginField("enable_tree_attention", nullptr, PluginFieldType::kINT32, 0));
1604	    mPluginAttributes.emplace_back(PluginField("enable_fp8_kv_cache", nullptr, PluginFieldType::kINT32, 0));
1605	    mPluginAttributes.emplace_back(PluginField("enable_vision_block_attention", nullptr, PluginFieldType::kINT32, 0));
1606	    // Sliding window size (-1 = no sliding window, >0 = window size)
1607	    mPluginAttributes.emplace_back(PluginField("sliding_window_size", nullptr, PluginFieldType::kINT32, 0));
1608	    // Optional QKV dequant scales [q, k, v] for FP8 attention
1609	    mPluginAttributes.emplace_back(PluginField("qkv_scales", nullptr, PluginFieldType::kFLOAT32, 0));
1610	    // Enforce Core parameters are specified.
1611	    mFieldCollection.nbFields = mPluginAttributes.size();
1612	    mFieldCollection.fields = mPluginAttributes.data();
1613	}
