1635	char const* AttentionPluginCreator::getPluginVersion() const noexcept
1636	{
1637	    return kATTENTION_PLUGIN_VERSION;
1638	}
1639	
1640	IPluginV3* AttentionPluginCreator::createPlugin(
1641	    char const* name, PluginFieldCollection const* fc, [[maybe_unused]] TensorRTPhase phase) noexcept
1642	{
1643	    try
1644	    {
1645	        auto* plugin = new AttentionPlugin(std::string(name), fc);
1646	        plugin->setPluginNamespace(mNamespace.c_str());
1647	        return plugin;
1648	    }
1649	    catch (std::exception const& e)
1650	    {
1651	        LOG_ERROR("Failed to create AttentionPlugin: %s", e.what());
1652	    }
1653	    return nullptr;
1654	}
1655	
1656	} // namespace plugins
1657	} // namespace trt_edgellm
