242	int32_t Int4GroupwiseGemmPlugin::enqueue(PluginTensorDesc const* inputDesc, PluginTensorDesc const* /* outputDesc */,
243	    void const* const* inputs, void* const* outputs, void* /* workspace */, cudaStream_t stream) noexcept
244	{
245	    try
246	    {
247	        auto const& inputDesc0 = inputDesc[0];
248	        int32_t const M = inputDesc0.dims.d[0] * inputDesc0.dims.d[1];
249	
250	        half* gemmInPtr = reinterpret_cast<half*>(const_cast<void*>(inputs[0]));
251	        int8_t* weightsInPtr = reinterpret_cast<int8_t*>(const_cast<void*>(inputs[1]));
252	        half* ScaleInPtr = reinterpret_cast<half*>(const_cast<void*>(inputs[2]));
253	        half* gemmOutDevicePtr = reinterpret_cast<half*>(outputs[0]);
254	
255	        // gemm_forward_cuda_new requires N divisible by its CTA_N tile size (128).
256	        // Smaller / non-aligned N (e.g. GDN's in_proj_a / in_proj_b = num_recurrent_heads
257	        // = 32 in Qwen3.5-4B) must use the GEMV kernel. GEMV only has template
258	        // instantiations for M=1..6, so split M into <=6-row chunks.
259	        // TODO: Iteration causes overhead. Need optimization if M is small and not divisible by 128. Possible
260	        // solutions: 1) Add more GEMV instantiations for larger M (e.g. 8, 16, 32). 2) Add a fallback GEMV kernel that
261	        // can handle arbitrary M without template instantiation (e.g. using dynamic shared memory).
262	        bool const useGemv = (M <= trt_edgellm::kernel::kGemvMaxM) || (mGemmN % trt_edgellm::kernel::kGemmCtaN != 0);
263	        if (useGemv)
264	        {
265	            for (int32_t m_start = 0; m_start < M; m_start += trt_edgellm::kernel::kGemvMaxM)
266	            {
267	                int32_t const m_chunk = std::min(trt_edgellm::kernel::kGemvMaxM, M - m_start);
268	                trt_edgellm::kernel::gemv_forward_cuda_new(gemmInPtr + m_start * mGemmK, weightsInPtr, ScaleInPtr,
269	                    gemmOutDevicePtr + m_start * mGemmN, m_chunk, mGemmN, mGemmK, mGroupSize, stream);
270	            }
271	        }
272	        else
273	        {
274	            trt_edgellm::kernel::gemm_forward_cuda_new(
275	                gemmInPtr, weightsInPtr, ScaleInPtr, gemmOutDevicePtr, M, mGemmN, mGemmK, mGroupSize, stream);
276	        }
277	        return 0;
278	    }
279	    catch (std::exception const& e)
280	    {
281	        return -1;
282	    }
